pub use std::marker::PhantomData;

/// Wraps a property's value type for the check below.
pub struct ValueCheck<T>(pub PhantomData<T>);

impl<T> Debug for ValueCheck<T> {
  fn fmt(&self, formatter: &mut Formatter<'_>) -> Result {
    formatter.write_str("ValueCheck")
  }
}

/// What `literal` returns for a property whose value is an element.
const TAKES_AN_ELEMENT: &str = "this property takes an element, not text";

/// What a property's thunks say they were given as text, for [`ValueError::WrongType`].
const TEXT: &str = "text";
/// What a property's thunks say they were given as a node, for [`ValueError::WrongType`].
const AN_ELEMENT: &str = "an element";

/// How a property's thunks turn what the loader holds into the value type `V`. The value check
/// returns it, so a property whose type can't be written in a UI language fails at that one check,
/// and its thunks report the same error at the same place.
#[derive(Debug)]
pub struct ValueOps<V> {
  /// Parses text, or says it didn't parse as `expected`.
  pub parse: fn(&str, &'static str) -> std::result::Result<V, ValueError>,
  /// Takes a node as the value, or refuses it.
  pub node: fn(NodeId, &'static str) -> std::result::Result<V, ValueError>,
}

/// Refuses a node: the value is text or an object.
fn not_a_node<V>(_node: NodeId, expected: &'static str) -> std::result::Result<V, ValueError> {
  Err(ValueError::WrongType {
    expected,
    found: AN_ELEMENT,
  })
}

/// Refuses text: the value is an element.
fn not_text<V>(_text: &str, expected: &'static str) -> std::result::Result<V, ValueError> {
  Err(ValueError::WrongType { expected, found: TEXT })
}

/// The value type can be written as text, and written back as Rust.
pub trait ViaFromStr {
  /// The property's value type.
  type Value;

  /// Compiles only for a value type a UI language can write, and gives the thunks' conversions.
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<Self::Value>;

  /// Parses `text` and writes the value it gives.
  fn write_literal(&self, text: &str, out: &mut RustExpr) -> std::result::Result<(), String>;
}

impl<T> ViaFromStr for ValueCheck<T>
where
  T: FromStr + ToRust,
  T::Err: Display,
{
  type Value = T;

  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<T> {
    ValueOps {
      parse: |text, expected| {
        text.parse().map_err(|error: T::Err| ValueError::Parse {
          expected,
          message: error.to_string(),
        })
      },
      node: not_a_node,
    }
  }

  fn write_literal(&self, text: &str, out: &mut RustExpr) -> std::result::Result<(), String> {
    let value: T = text.parse().map_err(|error: T::Err| error.to_string())?;
    value.to_rust(out);
    Ok(())
  }
}

/// The value type is itself a UI type, written as an object.
pub trait ViaUiType {
  /// The property's value type.
  type Value;

  /// Compiles only for a value type a UI language can write. Text and a node are both refused:
  /// the value is an object, which the loader moves in as one.
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<Self::Value> {
    ValueOps {
      parse: not_text,
      node: not_a_node,
    }
  }

  /// Refuses text: the value is an element.
  fn write_literal(&self, _text: &str, _out: &mut RustExpr) -> std::result::Result<(), String> {
    Err(TAKES_AN_ELEMENT.to_owned())
  }
}

impl<T: UiType> ViaUiType for &ValueCheck<T> {
  type Value = T;
}

/// The value is a child element, filled in by the element written inside.
pub trait ViaChild {
  /// Compiles only for a value type a UI language can write. Text is refused; a node is the value.
  fn value_must_parse_from_text_and_implement_torust_or_derive_uitype(&self) -> ValueOps<NodeId> {
    ValueOps {
      parse: not_text,
      node: |node, _| Ok(node),
    }
  }

  /// Refuses text: the value is an element.
  fn write_literal(&self, _text: &str, _out: &mut RustExpr) -> std::result::Result<(), String> {
    Err(TAKES_AN_ELEMENT.to_owned())
  }
}

impl ViaChild for &&ValueCheck<NodeId> {}

/// What a property's `set_object` says it was given when its value type isn't taken from an object.
const AN_OBJECT: &str = "an object";

/// Wraps a property's value type to choose how a staged object becomes it.
pub struct ObjectCheck<T>(pub PhantomData<T>);

impl<T> Debug for ObjectCheck<T> {
  fn fmt(&self, formatter: &mut Formatter<'_>) -> Result {
    formatter.write_str("ObjectCheck")
  }
}

/// The value type is taken from a staged object.
pub trait ViaFromUiObject {
  /// The property's value type.
  type Value;

  /// Takes the staged `object` out of the tree as the value.
  fn take_object(
    &self,
    tree: &mut UiTree,
    object: NodeId,
    expected: &'static str,
  ) -> std::result::Result<Self::Value, ValueError>;
}

impl<T: FromUiObject> ViaFromUiObject for ObjectCheck<T> {
  type Value = T;

  fn take_object(&self, tree: &mut UiTree, object: NodeId, _expected: &'static str) -> std::result::Result<T, ValueError> {
    check_staged(tree, object)?;
    T::from_object(tree, object)
  }
}

/// The value type isn't taken from an object: the staged object is taken out and refused.
pub trait NotFromObject {
  /// The property's value type.
  type Value;

  /// Takes the staged `object` out of the tree, so none is left behind, and refuses it.
  fn take_object(
    &self,
    tree: &mut UiTree,
    object: NodeId,
    expected: &'static str,
  ) -> std::result::Result<Self::Value, ValueError> {
    check_staged(tree, object)?;
    drop(tree.take(object));
    Err(ValueError::WrongType {
      expected,
      found: AN_OBJECT,
    })
  }
}

impl<T> NotFromObject for &ObjectCheck<T> {
  type Value = T;
}

/// Sets a value type's plain field, which `field` reaches in a `node` of the type `O`: the end of
/// a value type's [`PropertyAccess`] setters. A value has no precedence levels.
pub fn set_field<O: Object, T>(
  tree: &mut UiTree,
  node: NodeId,
  field: fn(&mut O) -> &mut T,
  value: T,
) -> std::result::Result<(), ValueError> {
  let owner = tree.get_as_mut::<O>(node).ok_or(ValueError::WrongNode)?;
  *field(owner) = value;
  Ok(())
}

/// Sets `value` at `level` on `node`'s property of the kind `key`: the end of every
/// [`PropertyAccess`] setter.
pub fn set_property<T>(
  tree: &UiTree,
  node: NodeId,
  key: &'static PropertyKey<T>,
  level: Precedence,
  value: T,
) -> std::result::Result<(), ValueError>
where
  T: PartialEq + 'static,
{
  crate::access::property_of(tree, node, key)?.set_at(level, value);
  Ok(())
}

/// Empties `level` of `node`'s property of the kind `key`: [`PropertyAccess::clear`].
pub fn clear_property<T>(
  tree: &UiTree,
  node: NodeId,
  key: &'static PropertyKey<T>,
  level: Precedence,
) -> std::result::Result<(), ValueError>
where
  T: PartialEq + 'static,
{
  crate::access::property_of(tree, node, key)?.clear(level);
  Ok(())
}

/// The function `PropertyInfo::literal` holds for a property of value type `$value`: `Some` with
/// the `literals` feature, `None` without, so an app's registry keeps no `ToRust` code.
#[cfg(feature = "literals")]
#[doc(hidden)]
#[macro_export]
macro_rules! __literal {
  ($value:ty) => {
    ::core::option::Option::Some({
      fn literal(text: &str, out: &mut $crate::RustExpr) -> ::core::result::Result<(), ::std::string::String> {
        use $crate::__private::{ViaChild as _, ViaFromStr as _, ViaUiType as _};
        (&&$crate::__private::ValueCheck::<$value>($crate::__private::PhantomData)).write_literal(text, out)
      }
      literal as $crate::WriteLiteral
    })
  };
}

/// The function `PropertyInfo::literal` holds for a property of value type `$value`: `Some` with
/// the `literals` feature, `None` without, so an app's registry keeps no `ToRust` code.
#[cfg(not(feature = "literals"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __literal {
  ($value:ty) => {
    ::core::option::Option::None
  };
}

pub use crate::__literal as literal;

/// The function `AttachedPropertyInfo::literal` holds for an attached property of type
/// `Option<$value>`: it writes the `$value` text gives inside `Some(...)`, since the owner's setter
/// takes the whole `Option`. `None` without the `literals` feature.
#[cfg(feature = "literals")]
#[doc(hidden)]
#[macro_export]
macro_rules! __optional_literal {
  ($value:ty) => {
    ::core::option::Option::Some({
      fn literal(text: &str, out: &mut $crate::RustExpr) -> ::core::result::Result<(), ::std::string::String> {
        let inner = $crate::__literal!($value).expect("the literals feature gives every value a literal");
        out.raw("::core::option::Option::Some(");
        inner(text, out)?;
        out.raw(")");
        ::core::result::Result::Ok(())
      }
      literal as $crate::WriteLiteral
    })
  };
}

/// The function `AttachedPropertyInfo::literal` holds for an attached property of type
/// `Option<$value>`: `None` without the `literals` feature.
#[cfg(not(feature = "literals"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __optional_literal {
  ($value:ty) => {
    ::core::option::Option::None
  };
}

pub use crate::__optional_literal as optional_literal;

/// Whether `a` and `b` are the same text, in const code.
const fn same_text(a: &str, b: &str) -> bool {
  let (a, b) = (a.as_bytes(), b.as_bytes());
  if a.len() != b.len() {
    return false;
  }
  let mut index = 0;
  while index < a.len() {
    if a[index] != b[index] {
      return false;
    }
    index += 1;
  }
  true
}

/// Whether a compiled view's code type is `path`, in const code.
pub const fn same_code_type(code_type: Option<&str>, path: &str) -> bool {
  match code_type {
    Some(code_type) => same_text(code_type, path),
    None => false,
  }
}

/// `name` without a raw identifier's `r#`, which a field's method name doesn't have, in const
/// code.
const fn unraw(name: &str) -> &str {
  match name.as_bytes() {
    [b'r', b'#', ..] => name.split_at(2).1,
    _ => name,
  }
}

/// Whether a group's `properties` hold a field named `name`, with or without `r#` on either side,
/// since `r#width` and `width` both get a method named `width`.
pub const fn group_has_field(properties: &[PropertyInfo], name: &str) -> bool {
  let mut index = 0;
  while index < properties.len() {
    if same_text(unraw(properties[index].field), unraw(name)) {
      return true;
    }
    index += 1;
  }
  false
}

/// Whether two groups' `properties` hold a field of one name.
pub const fn groups_share_field(a: &[PropertyInfo], b: &[PropertyInfo]) -> bool {
  let mut index = 0;
  while index < a.len() {
    if group_has_field(b, a[index].field) {
      return true;
    }
    index += 1;
  }
  false
}

/// Compiles only if `T` is a property group.
pub const fn assert_property_group<T: PropertyGroup>() {}

/// The content a flattened group gives the type that holds it in `field`.
pub const fn group_content(field: &'static str, info: Option<&'static PropertyInfo>) -> Option<ContentInfo> {
  match info {
    Some(info) => Some(ContentInfo::Property(PropertyRef {
      group: Some(field),
      info,
    })),
    None => None,
  }
}

/// The one content candidate that is set, if any.
///
/// # Panics
///
/// At compile time, when more than one is set: a type has at most one content member, counting the
/// groups it flattens.
pub const fn one_content(candidates: &[Option<ContentInfo>]) -> Option<ContentInfo> {
  let mut found = None;
  let mut index = 0;
  while index < candidates.len() {
    if let Some(candidate) = candidates[index] {
      assert!(
        found.is_none(),
        "a type has at most one `#[ui(content)]` member, counting the groups it flattens"
      );
      found = Some(candidate);
    }
    index += 1;
  }
  found
}

/// A collection a value's content may be: values taken from staged objects, never child nodes,
/// which taking the value out of the tree would free.
#[diagnostic::on_unimplemented(
  message = "a value's content is a collection of values, not `{Self}`",
  label = "a value can't hold child nodes",
  note = "use `Vec<T>` or `Arc<[T]>` of a value type, such as `Vec<GradientStop>`"
)]
pub trait ValueCollection {}

impl<T: FromUiObject> ValueCollection for Vec<T> {}

impl<T: FromUiObject + Clone> ValueCollection for std::sync::Arc<[T]> {}

/// Accepts only a [`ValueCollection`], so a value's generated code fails to compile on any other
/// content.
pub const fn value_collection<C: ValueCollection>() {}

/// A key a field may name its own default beside: a property key, through any number of
/// references. An attached key brings its own default, and two could disagree.
#[diagnostic::on_unimplemented(
  message = "`default` can't go beside an attached key",
  label = "this attached key already gives the field its default",
  note = "remove `default = ...`; the field starts at the attached property's default"
)]
pub trait TakesDefault {}

impl<T> TakesDefault for PropertyKey<T> {}

impl<K: TakesDefault + ?Sized> TakesDefault for &K {}

/// Returns `value`, the default a field names beside `key`, once the compiler has checked that
/// `key` may take one.
pub fn default_beside<K: TakesDefault + ?Sized, T>(key: &K, value: T) -> T {
  let _ = key;
  value
}

#[cfg(test)]
mod tests {
  use super::*;

  /// A group property whose field is written `field`.
  fn property(field: &'static str) -> PropertyInfo {
    PropertyInfo {
      name: "Width",
      field,
      value_type: "f32",
      affects: Affects::LAYOUT,
      inherits: false,
      literal: None,
      access: &crate::access::tests::UNWRITTEN,
    }
  }

  // A raw field and a plain one of the same name clash, either way round, since both get the
  // same method; another name doesn't.
  #[test]
  fn group_field_check_ignores_raw_spelling() {
    for (group, own) in [("width", "r#width"), ("r#width", "width"), ("r#width", "r#width")] {
      assert!(group_has_field(&[property(group)], own), "{group} and {own}");
    }
    assert!(!group_has_field(&[property("width")], "r#height"));
    assert!(!group_has_field(&[property("r")], "r#"));
  }

  #[derive(Debug)]
  struct Gauge;

  impl UiType for Gauge {
    const TYPE_INFO: &'static TypeInfo = &GAUGE;
  }

  static GAUGE: TypeInfo = TypeInfo {
    name: "Gauge",
    rust_path: "tests::Gauge",
    is: |_| false,
    new: None,
    content: None,
    properties: &[],
    groups: &[],
    events: &[],
    attached_properties: &[],
    value_provider: None,
    whitespace: Whitespace::Collapse,
    code_type_root: false,
    kind: TypeKind::Node,
  };

  // The check resolves for a FromStr type, a UI type and a child node. A type that is none of
  // them fails to compile, which the derive's compile-fail tests cover.
  #[test]
  #[allow(
    clippy::needless_borrow,
    reason = "the extra references pick the matching check, as in generated code"
  )]
  fn value_check_accepts_text_object_and_child_values() {
    (&&ValueCheck::<f32>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<Gauge>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
    (&&ValueCheck::<NodeId>(PhantomData)).value_must_parse_from_text_and_implement_torust_or_derive_uitype();
  }

  // A code type matches only the same whole path, and a view without one matches nothing.
  #[test]
  fn same_code_type_compares_whole_paths() {
    assert!(same_code_type(Some("app::views::LoginView"), "app::views::LoginView"));
    assert!(!same_code_type(Some("app::views::LoginView"), "app::views::LoginViews"));
    assert!(!same_code_type(Some("other::views::LoginView"), "app::views::LoginView"));
    assert!(!same_code_type(None, "app::views::LoginView"));
  }
}
